#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> pii;
char mazeX[15][15], mazeY[15][15];
int dirX[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
int nodeMap[65][15][15];
int maxCap[15][15];
int nodeCount = 1;

struct Edge {
  int u, v;
  long long cap, flow;
  Edge() {}
  Edge(int u, int v, long long cap): u(u), v(v), cap(cap), flow(0) {}
};

struct DinicAlgorithm {
  int totalNodes;
  vector<Edge> edges;
  vector<vector<int>> adjList;
  vector<int> level, ptr;

  DinicAlgorithm(int N): totalNodes(N), edges(), adjList(N), level(N), ptr(N) {}

  void addEdge(int u, int v, long long cap) {
    if (u != v) {
      edges.emplace_back(Edge(u, v, cap));
      adjList[u].push_back(edges.size() - 1);
      edges.emplace_back(Edge(v, u, 0));
      adjList[v].push_back(edges.size() - 1);
    }
  }

  bool buildLevelGraph(int S, int T) {
    queue<int> q({S});
    fill(level.begin(), level.end(), totalNodes + 1);
    level[S] = 0;
    while (!q.empty()) {
      int u = q.front(); q.pop();
      if (u == T) break;
      for (int e_idx: adjList[u]) {
        Edge &e = edges[e_idx];
        if (e.flow < e.cap && level[e.v] > level[e.u] + 1) {
          level[e.v] = level[e.u] + 1;
          q.push(e.v);
        }
      }
    }
    return level[T] != totalNodes + 1;
  }

  long long pushFlow(int u, int T, long long flow = -1) {
    if (u == T || flow == 0) return flow;
    for (int &i = ptr[u]; i < (int)adjList[u].size(); ++i) {
      Edge &e = edges[adjList[u][i]];
      Edge &oe = edges[adjList[u][i]^1];
      if (level[e.v] == level[e.u] + 1) {
        long long amt = e.cap - e.flow;
        if (flow != -1 && amt > flow) amt = flow;
        long long pushed = pushFlow(e.v, T, amt);
        if (pushed > 0) {
          e.flow += pushed;
          oe.flow -= pushed;
          return pushed;
        }
      }
    }
    return 0;
  }

  long long getMaxFlow(int S, int T) {
    long long totalFlow = 0;
    while (buildLevelGraph(S, T)) {
      fill(ptr.begin(), ptr.end(), 0);
      while (long long flow = pushFlow(S, T))
        totalFlow += flow;
    }
    return totalFlow;
  }
};

int main() {
  memset(maxCap, -1, sizeof(maxCap));
  int n, t;
  scanf("%d%d", &n, &t);
  for (int i=1; i<=n; i++) {
    scanf("%s", mazeX[i]+1);
  }
  for (int i=0; i<=t+1; i++) {
    for (int j=1; j<=n; j++) {
      for (int k=1; k<=n; k++) {
        nodeMap[i][j][k] = nodeCount++;
      }
    }
  }
  nodeCount++;
  for (int i=1; i<=n; i++) {
    scanf("%s", mazeY[i]+1);
  }
  queue<pii> q;
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeX[i][j] == 'Z') {
        q.push({i, j});
        maxCap[i][j] = 0;
      }
    }
  }
  while (!q.empty()) {
    int y = q.front().first, x = q.front().second;
    q.pop();
    for (int i=0; i<4; i++) {
      int ny = y + dirX[i][0], nx = x + dirX[i][1];
      if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && mazeX[ny][nx] != 'Y' && maxCap[ny][nx] == -1) {
        maxCap[ny][nx] = maxCap[y][x] + 1;
        q.push({ny, nx});
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (maxCap[i][j] == -1) maxCap[i][j] = 1e9;
      if (maxCap[i][j] > t) maxCap[i][j] = 1e9;
    }
  }
  int s = 0, t_node = nodeCount - 1;
  DinicAlgorithm flowNet(nodeCount);
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeX[i][j] >= '1' && mazeX[i][j] <= '9') {
        flowNet.addEdge(s, nodeMap[0][i][j], mazeX[i][j]-'0');
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeX[i][j] == 'Y' || mazeX[i][j] == 'Z') continue;
      for (int k=0; k<4; k++) {
        int ny = i + dirX[k][0], nx = j + dirX[k][1];
        if (ny >= 1 && ny <= n && nx >= 1 && nx <= n && mazeX[ny][nx] != 'Y' && mazeX[ny][nx] != 'Z') {
          for (int x=0; x<t; x++) {
            if (maxCap[ny][nx] >= x+1 && maxCap[i][j] > x) {
              flowNet.addEdge(nodeMap[x][i][j], nodeMap[x+1][ny][nx], 1000);
            }
          }
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeX[i][j] == 'Y' || mazeX[i][j] == 'Z') continue;
      for (int x=0; x<=t; x++) {
        if (mazeY[i][j] >= '1' && mazeY[i][j] <= '9') {
          flowNet.addEdge(nodeMap[x][i][j], nodeMap[t+1][i][j], mazeY[i][j]-'0');
        }
      }
    }
  }
  for (int i=1; i<=n; i++) {
    for (int j=1; j<=n; j++) {
      if (mazeX[i][j] == 'Y' || mazeX[i][j] == 'Z') continue;
      if (mazeY[i][j] >= '1' && mazeY[i][j] <= '9') {
        flowNet.addEdge(nodeMap[t+1][i][j], t_node, mazeY[i][j]-'0');
      }
    }
  }
  printf("%lld\n", flowNet.getMaxFlow(s, t_node));
}
